?>
<div class="site-theme" style="--site-accent:<?=e(valid_accent($site['accent']))?>"><header class="mini-nav article-nav section-shell"><a class="mini-brand" href="<?=e(app_url('site.php?slug='.rawurlencode($site['slug'])))?>"><img src="<?=e(safe_asset_url($site['avatar'],'assets/images/avatar-default.svg'))?>" alt=""><span><?=e($site['name'])?></span></a><a href="<?=e(app_url('site.php?slug='.rawurlencode($site['slug'])))?>">← Tous les articles</a></header><main class="article-page section-shell"><article><div class="article-meta"><span><?=e($article['category'])?></span><time><?=e(substr((string)$article['published_at'],0,10))?></time></div><h1><?=e($article['title'])?></h1><p class="article-deck"><?=e($article['excerpt']?:excerpt($article['content'],240))?></p><img class="article-hero-image" src="<?=e(safe_asset_url($article['image']))?>" alt=""><div class="article-prose"><?=nl2br(e($article['content']))?></div><?php if(trim((string)$article['tags'])!==''):?><div class="tag-row"><?php foreach(array_filter(array_map('trim',explode(',',$article['tags']))) as $tag):?><span>#<?=e($tag)?></span><?php endforeach;?></div><?php endif;?></article><aside class="author-card"><img src="<?=e(safe_asset_url($site['avatar'],'assets/images/avatar-default.svg'))?>" alt=""><span>Publié sur</span><h3><?=e($site['name'])?></h3><p><?=e($site['tagline'])?></p><a class="btn btn-ghost btn-full" href="<?=e(app_url('site.php?slug='.rawurlencode($site['slug'])))?>">Voir le site</a></aside></main><footer class="mini-footer section-shell"><span>Propulsé par <a href="<?=e(app_url())?>">Nova CMS</a></span><span>Open source · PHP</span></footer></div>
